function amountFor(a,s,t,acts=[...active,...planned.values()]){const m=D.measures[a.index];const sources=a.funding.filter(f=>f.source_id===s.id);if(!sources.length||t<a.start)return 0;const source=sources.reduce((sum,f)=>({initial_amount:sum.initial_amount+f.initial_amount,quarterly_amount:sum.quarterly_amount+f.quarterly_amount}),{initial_amount:0,quarterly_amount:0});const end=H.actionEnd(m,a)-1;const c=costs(m,a.intensity,a.start,a);if(t>end)return c.maintenance && c.quarter?c.maintenance*source.quarterly_amount/c.quarter:0;return sources.reduce((sum,f)=>{const amount=f.quarterly_amount+(t===a.start?f.initial_amount:0);return sum+(s.kind==='tax_increase'&&(!f.locked||amount>0)?amount*fiscalScope(s,t,acts)/(f.scope_fraction??1):amount);},0);}
