 if(effect){if(R.coherence&&m.price_control){controlledRent+=effect.price.rent;controlledSale+=effect.price.sale;}else{rent+=effect.price.rent;sale+=effect.price.sale;}free+=effect.price.free_rent;for(const [id,amount]of Object.entries(effect.groups)){const i=slotFor(id);if(i>=0)happiness[i]+=amount;}}
