 if(m.category==='admin'&&!m.admin_program)adminForce=Math.max(adminForce,force);if(m.category==='supply')buildForce=Math.max(buildForce,force*(m.effect_scale??1));if(m.id.includes('rent_aid'))aidForce=Math.max(aidForce,force);if(m.exclusive_group==='rent_control')controlForce=Math.max(controlForce,force);
