function deltas(m,x){const a=typeof draft!=='undefined'&&draft&&D.measures[draft.index]?.id===m.id?{...draft,intensity:x}:{intensity:x};const social=H.accessManagement(m,a).capacity*H.durationHappiness(m,a)*(m.migration_program?.bonus?H.migrationCapacity(m,a)/(m.migration_program.annual_capacity*x||1):1);const v=m.happiness.map((h,i)=>h*policyIntensity(m,x)*social-riskAt(m,x)*(i===2?R.risk_tenant_points:i===1?R.risk_investor_points:0));v.extraGroups=Object.fromEntries((D.extra_groups||[]).map(g=>[g.id,(m.effects||[]).filter(e=>e.target_type==='group'&&e.target_id===g.id).reduce((n,e)=>n+e.amount,0)*policyIntensity(m,x)*social]));return v;}
