 $('open-policy').onclick=()=>openPolicy(current);$('count').textContent=planned.size+' / '+R.max_measures_per_turn+' medidas seleccionadas';renderRecap();
 if(m.temporal_control||m.term_control||m.tourism_program?.kind==='ban'){const running=active.find(x=>x.index===current&&H.actionEnd(m,x)>turn+1);if(running){$('open-policy').disabled=true;$('open-policy').textContent='Activa hasta '+quarterLabel(H.actionEnd(m,running)-2);$('detail').insertAdjacentHTML('beforeend','<button class="quiet" id="cancel-active-policy">Cancelar desde el próximo trimestre</button>');$('cancel-active-policy').onclick=()=>cancelActivePolicy(active.indexOf(running));}}
