 if(m.supply_program){const running=active.find(x=>x.index===current&&x.start+m.duration_turns-1>=turn+1),used=active.filter(x=>x.index===current).reduce((n,x)=>n+x.intensity*m.supply_program.max_homes,0);if(running){$('open-policy').disabled=true;$('open-policy').textContent='En ejecución hasta '+quarterLabel(running.start+m.duration_turns-2);}else if(used>=m.supply_program.lifetime_homes-.01){$('open-policy').disabled=true;$('open-policy').textContent='Capacidad de la partida agotada';}}
