function cancelActivePolicy(index){const a=active[index],m=a&&D.measures[a.index];if(!(m?.temporal_control?.cancellable||m?.term_control?.cancellable||m?.tourism_program?.kind==='ban')||H.actionEnd(m,a)<=turn+1)return;a.cancelled_turn=turn+1;render();error('Medida desactivada desde '+quarterLabel(turn)+'. El historial y los costes anteriores se conservan.');}
