 draft=planned.has(index)?structuredClone(planned.get(index)):{index,intensity:D.measures[index].default_intensity??.5,funding:[],shares:{},start:turn+1};draft.shares||={};selectedSource=Object.keys(draft.shares)[0]||null;
 const m=D.measures[index];if(m.tax_control){draft.tax_bases??={};draft.tax_rates??={};draft.tax_carrier??=m.tax_control.default_carrier;for(const c of m.tax_control.components){const src=D.funding_sources.find(s=>s.id===c.source_id);draft.tax_bases[c.id]??=c.mode==='cut'&&src&&!c.protected_scope?Math.round(sourceCurrentValue(src)/c.step)*c.step:c.base;draft.tax_rates[c.id]??=draft.tax_bases[c.id];}draft.intensity=H.taxForce(m,draft);}if(m.term_control)draft.duration_turns??=m.term_control.default_turns;if(m.tourism_program){const p=m.tourism_program;if(p.kind==='days')draft.days_allowed??=Math.round(p.max_days-(p.max_days-p.min_days)*draft.intensity);if(p.kind==='licenses')draft.annual_licenses??=Math.round(p.annual_new*(1-draft.intensity)/p.license_step)*p.license_step;if(p.kind==='inspection')draft.inspectors??=Math.max(p.min_inspectors,Math.round(p.max_inspectors*draft.intensity/p.inspector_step)*p.inspector_step);if(p.kind==='ban')draft.policy_enabled??=true;draft.intensity=H.tourismForce(m,draft);}if(m.temporal_control){draft.duration_turns??=m.temporal_control.default_turns;draft.intensity=1;}if(m.access_program)draft.purchase_price??=history[turn]?.[7]??D.prices.sale.value;if(m.existing_program){const pool=listingValues(history[turn]||initialState()).sale,p=m.existing_program;draft.sale_pool=pool;draft.quantity_max=Math.floor(pool*p.max_sale_share);draft.units??=Math.min(draft.quantity_max,Math.max(1,Math.round(draft.quantity_max*.1)));draft.purchase_price??=history[turn]?.[7]??D.prices.sale.value;draft.rent_reference??=history[turn]?.[6]??D.prices.rent.value;draft.intensity=draft.units/p.reference_homes;}if(m.insurance_program)draft.rent_reference??=history[turn]?.[6]??D.prices.rent.value;draft.construction_cost_factor??=H.constructionCostFactor(D,turn+1,active);draft.tax_support??=m.tax_support?.default??0;draft.return_bonus??=m.migration_program?.bonus?.default;draft.management??=m.access_program?.management?.default;draft.enforcement??=m.price_control?.default_enforcement;draft.reference_price??=history[turn]?.[m.price_control?.mode==='sale'?7:6]??D.prices.rent.value;if(!m.existing_program&&!m.tax_control&&!m.tourism_program)draft.intensity=quantizeIntensity(m,draft.intensity);$('intensity').min=(m.intensity_min??.01)*100;$('intensity').max=(m.intensity_max??1)*100;$('intensity').step=(m.intensity_step??.01)*100;$('policy-title').textContent=m.name;$('policy-explanation').textContent=m.mechanism+'.';$('intensity').value=draft.intensity*100;$('modal-effects').innerHTML=effectsHTML(m);
