 draft.funding=entries.map(([source_id,share],i)=>{const last=i===entries.length-1&&Math.abs(covered-100)<.001;const initial_amount=last?c.initial-paidI:Math.round(c.initial*share)/100;const quarterly_amount=last?c.quarter-paidQ:Math.round(c.quarter*share)/100;paidI+=initial_amount;paidQ+=quarterly_amount;return {source_id,initial_amount,quarterly_amount,scope_fraction:H.fundingScopeFraction(D,source_id,turn+1,[...active,...[...planned.values()].filter(a=>a.index!==draft.index),draft])};});
 for(const receipt of H.taxReceipts(D.measures[draft.index],draft,moneyIndex(turn+1)))if(receipt.source_id)draft.funding.push({source_id:receipt.source_id,initial_amount:0,quarterly_amount:receipt.quarterly_amount,locked:true,receipt:true});
