$('enforcement').oninput=e=>{if(D.measures[draft.index].migration_program?.bonus)draft.return_bonus=+e.target.value;else if(D.measures[draft.index].access_program?.management)draft.management=+e.target.value;else draft.enforcement=+e.target.value/100;updateDraft()};
$('tax-support').oninput=e=>{const p=D.measures[draft.index].tax_support,r=p.rate_control;draft.tax_support=r?(r.base-+e.target.value)/(r.base-r.min):+e.target.value/(p.max_annual/1e6);updateDraft()};
$('intensity').oninput=e=>{const m=D.measures[draft.index];if(m.tourism_program){const p=m.tourism_program,key={days:'days_allowed',licenses:'annual_licenses',inspection:'inspectors'}[p.kind];if(key)draft[key]=+e.target.value;draft.intensity=H.tourismForce(m,draft);updateDraft();return;}if(m.tax_control){const c=m.tax_control.components[0];draft.tax_rates[c.id]=+e.target.value;draft.intensity=H.taxForce(m,draft);updateDraft();return;}if(m.temporal_control){draft.duration_turns=Math.round(clamp(+e.target.value,m.temporal_control.min_turns,m.temporal_control.max_turns));updateDraft();return;}if(m.existing_program){draft.units=Math.round(clamp(+e.target.value,1,draft.quantity_max));draft.intensity=draft.units/m.existing_program.reference_homes;updateDraft();return;}const scale=m.budget_control?m.quarterly_cost*moneyIndex(turn+1)*(m.budget_control.period==='annual'?4:1)/1e6:m.quantity_control?m.quantity_control.max:m.admin_program?m.quarterly_cost*moneyIndex(turn+1)/1e6:100;draft.intensity=quantizeIntensity(m,+e.target.value/scale);updateDraft()};
