function chooseSource(e){const b=e.target.closest('[data-source]');if(b){selectedSource=b.dataset.source;renderFunding();$('funding-intensity').focus({preventScroll:true});$('funding-editor').scrollIntoView({behavior:'instant',block:'nearest'});}}
$('funding-map').onclick=chooseSource;$('funding-summary').onclick=chooseSource;
$('funding-intensity').oninput=e=>setSourceValue(+e.target.value);
